// Verifies a UniFi Access webhook and answers it.
// Output 1: verified event (msg.payload = parsed JSON)
// Output 2: HTTP response for UniFi Access
const MAX_AGE_SECONDS = 300; // reject signatures older than 5 minutes (replay protection)
const secret = env.get("UNIFI_ACCESS_WEBHOOK_SECRET");

function respond(code, text) {
    return { req: msg.req, res: msg.res, statusCode: code, payload: text };
}
function reject(code, reason) {
    node.warn("UniFi webhook rejected: " + reason);
    node.status({ fill: "red", shape: "ring", text: reason });
    return [null, respond(code, reason)];
}

if (!secret) {
    node.error("Environment variable UNIFI_ACCESS_WEBHOOK_SECRET is not set");
    return reject(500, "not configured");
}

let body = msg.payload;
if (typeof body === "string") body = Buffer.from(body, "utf8");
if (!Buffer.isBuffer(body)) {
    node.error("The HTTP In node must have 'Do not parse body' enabled so the raw body can be verified");
    return reject(500, "raw body unavailable");
}

const header = String((msg.req && msg.req.headers && msg.req.headers["signature"]) || "");
const parts = {};
for (const part of header.split(",")) {
    const i = part.indexOf("=");
    if (i > 0) parts[part.slice(0, i).trim()] = part.slice(i + 1).trim();
}
const t = parts.t;
const v1 = parts.v1;
if (!t || !/^\d+$/.test(t) || !v1 || !/^[0-9a-fA-F]{64}$/.test(v1)) {
    return reject(401, "missing or malformed signature");
}
if (Math.abs(Date.now() / 1000 - Number(t)) > MAX_AGE_SECONDS) {
    return reject(401, "signature expired");
}

const expected = crypto
    .createHmac("sha256", secret)
    .update(Buffer.concat([Buffer.from(t + ".", "utf8"), body]))
    .digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(v1, "hex"))) {
    return reject(401, "invalid signature");
}

// Ignore exact repeats of a valid delivery
const seen = flow.get("unifiAccessSeenSignatures") || [];
if (seen.includes(v1)) {
    node.status({ fill: "yellow", shape: "ring", text: "duplicate ignored" });
    return [null, respond(200, "duplicate")];
}
seen.push(v1);
flow.set("unifiAccessSeenSignatures", seen.slice(-100));

let event;
try {
    event = JSON.parse(body.toString("utf8"));
} catch (err) {
    return reject(400, "invalid JSON");
}

node.status({ fill: "green", shape: "dot", text: (event.event || "event") + " verified" });
return [{ payload: event, topic: event.event }, respond(200, "ok")];

// Map each UniFi Access door to its Level lock.
// Keys can be the UniFi door ID or the door name exactly as shown in UniFi Access.
// Unmatched doors are logged in the debug sidebar with their ID and name.
const DOORS = {
    "Front Door": "lock.front_door",
    "Garage": "lock.garage",
};

const event = msg.payload || {};
if (event.event !== "access.door.unlock") return null;

const data = event.data || {};
const door = data.location || {};
const access = data.object || {};

if (access.result && /denied|block|reject|fail/i.test(access.result)) {
    node.warn(`Access not granted at "${door.name}": ${access.result}`);
    return null;
}

const entity = DOORS[door.id] || DOORS[door.name];
if (!entity) {
    node.warn(`No Level lock mapped for UniFi door "${door.name}" (id ${door.id}). Add it to DOORS.`);
    node.status({ fill: "yellow", shape: "ring", text: `unmapped: ${door.name}` });
    return null;
}

const who = (data.actor && data.actor.name) || "unknown";
node.status({ fill: "green", shape: "dot", text: `${door.name} → ${entity} (${who})` });
return {
    payload: { action: "lock.unlock", target: { entity_id: [entity] } },
    unifi: {
        door: door.name,
        door_id: door.id,
        actor: who,
        method: access.authentication_type,
        reader_id: access.reader_id,
    },
};
